// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {CVXStaker, ICVXBooster, IERC20} from "../src/CVXStaker.sol";

contract InvMutTest is Test {
    CVXStaker c;

    function setUp() public {
        c = new CVXStaker(address(new __InvMutHandleStub()), IERC20(address(this)), ICVXBooster(address(this)), new address[](0));
    }

    function testFuzz_property(address newRecipient) public {
        // Any address is admissible as a recipient (including 0, which the setter allows)
        vm.prank(c.owner());
        c.setRewardsRecipient(newRecipient);
        // General rule: after the owner sets the recipient, the stored recipient equals the argument.
        assertTrue(c.rewardsRecipient() == newRecipient);
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
